import * as THREE from 'three/webgpu';
import {
	MeshBasicNodeMaterial,
	texture,
	uv,
	rotateUV,
	vec4,
	multiply,
	add,
	subtract,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {[number,number,number]} position
 * @property {[number,number,number]} rotation
 * @property {[number,number,number]} scale
 * @property {string} textContent
 * @property {{index:number, rect:[number,number,number,number]}} atlas
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load:(url:string)=>THREE.Texture}} textureLoader
 * @property {Object<string,Function>} primitives
 * @property {{createTextMaterial:(atlasIndex:number, text:string, options:any)=>THREE.Material}} fontAtlas
 */

/**
 * Create a textured plane with optional SDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// ------- Resources -------
	const disposables = [];

	// Load background image texture
	const bgTexture = ctx.textureLoader.load(config.assets.imageUrl);
	if (bgTexture) disposables.push(bgTexture);

	// Determine plane size from texture aspect (fallback to 1:1)
	const aspect = bgTexture?.image?.width && bgTexture?.image?.height
		? bgTexture.image.width / bgTexture.image.height
		: 1.6; // default aspect from spec (512/320)

	const planeGeo = new THREE.PlaneGeometry(aspect, 1);
	disposables.push(planeGeo);

	// Background material (unlit)
	const bgMaterial = new MeshBasicNodeMaterial({
		map: texture(bgTexture),
		transparent: true,
	});
	disposables.push(bgMaterial);

	const bgMesh = new THREE.Mesh(planeGeo, bgMaterial);
	bgMesh.name = 'pricing-card-bg';

	// ------- Text overlay using font atlas -------
	// Expect ctx.fontAtlas to expose a method that returns a material
	// capable of rendering SDF text from a region of an atlas.
	// The implementation detail is abstracted away; we only pass in the
	// necessary parameters.

	const textMaterial = ctx.fontAtlas.createTextMaterial(
		config.atlas?.index ?? 0,
		config.textContent,
		{
			color: new THREE.Color('#16161d'), // ink color
			size: 0.13, // type scale for body text (scene‑unit)
			// The source rect within the atlas (x, y, w, h)
			rect: config.atlas?.rect ?? [0, 0, 512, 320],
			// Ensure the text respects the plane geometry UVs
			uvNode: uv(),
		}
	);
	if (textMaterial) disposables.push(textMaterial);

	const textMesh = new THREE.Mesh(planeGeo, textMaterial);
	textMesh.name = 'pricing-card-text';
	textMesh.renderOrder = 1; // render above background

	// ------- Assemble node -------
	const node = new THREE.Object3D();
	node.name = 'pricing-card-3-label';
	node.position.set(...config.position);
	node.rotation.set(...config.rotation);
	node.scale.set(...config.scale);
	node.add(bgMesh);
	node.add(textMesh);

	// Apply cinematic primitives if any
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				fn(node, prim.params);
			}
		}
	}

	// ------- Event handlers placeholder -------
	node.userData.handlers = {};

	// ------- Cleanup ----------
	node.userData.cleanup = () => {
		// Dispose geometry & materials
		disposables.forEach((res) => {
			if (res && typeof res.dispose === 'function') {
				res.dispose();
			}
		});
		// Kill any GSAP timelines attached to this node
		gsap.killTweensOf(node);
		// Clear references
		node.traverse((child) => {
			child.userData = {};
		});
	};

	return node;
}
